import React from "react";
import { Truck, MapPin, CheckCircle } from "lucide-react";

const pickups = [
  {
    id: 1,
    sector: "Sector 04",
    bin: "BIN_203",
    time: "07:00",
  },
  {
    id: 2,
    sector: "Zone B",
    bin: "BIN_552",
    time: "09:30",
  },
];

const ScheduleTab = () => {
  return (
    <div className="w-full max-w-[1100px]">

      {/* HEADER */}

      <div className="mb-12">
        <p className="text-[10px] font-black uppercase tracking-[0.5em] text-[#A1AED1]">
          Dispatch_System
        </p>

        <h2 className="text-7xl font-black italic text-[#47510B] uppercase tracking-tighter">
          Today’s <span className="text-[#FF5B03]">Route.</span>
        </h2>
      </div>

      {/* PICKUP CARDS */}

      <div className="grid grid-cols-2 gap-8">

        {pickups.map((p) => (
          <div
            key={p.id}
            className="group bg-white rounded-[50px] p-10 shadow-[0_30px_80px_rgba(161,174,209,0.2)] 
                       hover:-translate-y-3 hover:shadow-[0_40px_100px_rgba(161,174,209,0.4)]
                       transition-all duration-500 cursor-pointer relative overflow-hidden"
          >

            {/* ICON */}

            <div className="w-16 h-16 bg-[#CAD23C] text-[#47510B] rounded-[24px] flex items-center justify-center mb-8 shadow-xl group-hover:rotate-12 transition-transform">
              <Truck size={30} />
            </div>

            {/* CONTENT */}

            <h3 className="text-3xl font-black italic text-[#47510B] uppercase tracking-tight">
              {p.sector}
            </h3>

            <p className="text-xs font-black uppercase text-[#A1AED1] tracking-widest mt-2">
              {p.time}
            </p>

            <div className="flex items-center gap-2 text-[#47510B] mt-4 font-bold text-sm">
              <MapPin size={14} />
              {p.bin}
            </div>

            {/* ACTION */}

            <button
              className="mt-8 bg-[#47510B] text-[#CAD23C] px-6 py-4 rounded-2xl 
                         font-black uppercase text-sm tracking-widest
                         shadow-[0_6px_0_0_#2A3106]
                         active:translate-y-1 active:shadow-none
                         transition-all flex items-center gap-2"
            >
              <CheckCircle size={16} />
              Complete
            </button>

            {/* BACKGROUND GRAPHIC */}

            <div className="absolute -right-10 -bottom-10 text-[200px] opacity-[0.04] font-black italic text-[#47510B] pointer-events-none">
              T
            </div>

          </div>
        ))}

      </div>

    </div>
  );
};

export default ScheduleTab;
